package httpserver

import (
	"io"
	"net/http"
)

func renderProjectCompletion(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, projectCompletionPage)
}

func projectCompletionScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, projectCompletionJavaScript)
}

const projectCompletionPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project 完成检查点</title><style>` + projectCompletionCSS + `[hidden]{display:none!important}</style></head><body>
<header class="top"><a class="brand" href="../"><span>PW</span><strong>项目工作空间</strong></a><div class="top-actions"><a href="../">返回项目台账</a><button id="openCredential" class="quiet">设置访问凭证</button></div></header><main>
<section class="header"><p class="eyebrow">Reference OA · C5</p><h1>Project 完成条件检查点</h1><p>这里验证“批复结果”和“审计结果”是否都存在且可追溯。它是 C5 的版本化检查点，不等于整个 OA Project 已完成；C6／C7 尚未纳入。</p></section>
<form id="projectForm" class="project-bar"><label>Project ID<input id="projectID" required placeholder="稳定 UUID"></label><button class="quiet" type="submit">只读评估</button></form><div id="notice" class="notice">GET 评估不会写 Project，也不会修改 Results。</div>
<div class="grid"><section class="panel"><div class="panel-head"><div><h2>当前评估</h2><span id="observed">尚未读取</span></div><span id="overall" class="status">—</span></div><div id="requirements" class="requirements"><div class="empty">输入 Project ID 开始评估。</div></div><button id="confirm" class="primary full" disabled>显式确认当前 C5 检查点</button><p class="boundary">确认只在 Project Workspace 写入一个新 revision 和不可变来源快照；不会调用 Results 写接口，也不会把 Project 状态伪装成“全 OA 已完成”。</p></section>
<aside class="panel"><div class="panel-head"><div><h2>最近确认</h2><span>冻结的精确来源</span></div><span id="drift" class="status">未确认</span></div><div id="confirmation" class="confirmation"><div class="empty">满足条件后才可显式确认。</div></div></aside></div>
</main><dialog id="credentialDialog"><form method="dialog" id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护 Project API</h2><p>正式组合由 Gateway 使用 IAM 会话签发短期 Project Credential。本地 Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">保存并评估</button></div></form></dialog><script src="../assets/completion.js"></script></body></html>`

const projectCompletionCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#18212f;background:#f4f6f8;line-height:1.55;--muted:#667085;--line:#dce1e8;--soft:#f7f8fa;--accent:#3157a4;--warning:#8a5a00;--danger:#a93a33}*{box-sizing:border-box}body{margin:0}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;color:#18212f;text-decoration:none}.brand span{display:grid;place-items:center;width:34px;height:34px;border-radius:7px;background:#243b66;color:#fff;font-size:12px;font-weight:800}.top-actions,.dialog-actions{display:flex;align-items:center;gap:10px}.top-actions a{color:var(--accent);font-size:13px;font-weight:700}main{max-width:1180px;margin:0 auto;padding:40px 28px}.header{max-width:760px}.eyebrow{margin:0 0 8px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}h1{margin:0 0 12px;font-size:34px;letter-spacing:-.025em}.header>p:not(.eyebrow){color:var(--muted)}.project-bar{display:grid;grid-template-columns:minmax(280px,640px) auto;gap:10px;align-items:end;margin-top:28px;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fff}.notice{margin:12px 0 16px;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#922}.grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,.75fr);gap:16px}.panel{min-height:450px;padding:20px;border:1px solid var(--line);border-radius:10px;background:#fff}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding-bottom:14px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:18px}.panel-head span:not(.status){color:var(--muted);font-size:12px}.status{padding:4px 9px;border-radius:999px;background:#eef1f4;color:#566273;font-size:11px;font-weight:800}.status.satisfied{background:#eaf6ef;color:#26734d}.status.pending,.status.drifted{background:#fff5df;color:var(--warning)}.status.unavailable{background:#fff0f0;color:var(--danger)}.requirements,.confirmation{display:grid;gap:10px;margin:16px 0}.requirement,.source{padding:14px;border:1px solid var(--line);border-radius:7px;background:var(--soft)}.requirement header{display:flex;align-items:center;justify-content:space-between}.requirement strong{font-size:14px}.requirement p,.source p{margin:6px 0 0;color:var(--muted);font-size:12px}.source code{font-size:11px;word-break:break-all}.full{width:100%}.boundary{margin:12px 0 0;color:var(--muted);font-size:12px}.empty{display:grid;place-content:center;min-height:150px;color:var(--muted);text-align:center}.primary,.quiet{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet{border-color:var(--line);background:#fff;color:#3f4a5a}.primary:disabled{opacity:.45;cursor:not-allowed}label{display:grid;gap:5px;color:#4c5667;font-size:12px;font-weight:700}input,textarea{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;color:#18212f;font:inherit;font-size:13px}dialog{width:min(620px,calc(100vw - 32px));padding:24px;border:1px solid var(--line);border-radius:11px;box-shadow:0 18px 50px #18212f2a}dialog::backdrop{background:#18212f66}.dialog-actions{justify-content:flex-end;margin-top:18px}@media(max-width:820px){main{padding:24px 16px}.grid,.project-bar{grid-template-columns:1fr}}`

const projectCompletionJavaScript = `const $=s=>document.querySelector(s),state={token:sessionStorage.getItem('project-demo-token')||'',projectID:'',assessment:null};const PROFILE='reference-oa-c5-v1',CONFIRM='project-workspace.completion.confirm';
function notice(message,kind=''){const n=$('#notice');n.textContent=message;n.className='notice '+kind}async function api(path,options={}){const r=await fetch(path,{...options,headers:{Accept:'application/json',Authorization:'Bearer '+state.token,...(options.body?{'Content-Type':'application/json'}:{})}}),b=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(b.error?.code||'HTTP_'+r.status);e.status=r.status;e.retryable=b.error?.retryable;throw e}return b}function esc(v){const s=document.createElement('span');s.textContent=v??'';return s.innerHTML}
function sources(){return (state.assessment?.requirements||[]).filter(x=>x.status==='satisfied'&&x.source).map(x=>({requirement_key:x.key,result_id:x.source.id,result_kind:x.source.kind,revision:x.source.revision,digest:x.source.digest})).sort((a,b)=>a.requirement_key.localeCompare(b.requirement_key))}
function render(){const a=state.assessment;if(!a)return;$('#observed').textContent='Project revision '+a.project_revision+' · '+new Date(a.observed_at).toLocaleString('zh-CN');$('#overall').textContent=a.overall_status;$('#overall').className='status '+a.overall_status;$('#requirements').innerHTML=a.requirements.map(x=>'<article class="requirement"><header><strong>'+esc(x.key==='approval_result_recorded'?'批复结果':'审计结果')+'</strong><span class="status '+x.status+'">'+esc(x.status)+'</span></header><p>'+esc(x.reason)+'</p>'+(x.source?'<p>来源：'+esc(x.source.id)+' · revision '+x.source.revision+' · '+esc(x.source.digest.slice(0,16))+'…</p>':'')+'</article>').join('');$('#confirm').disabled=!(a.allowed_actions||[]).includes(CONFIRM)||a.overall_status!=='satisfied';const c=a.latest_confirmation;$('#drift').textContent=!c?'未确认':a.drifted?'来源已漂移':'来源一致';$('#drift').className='status '+(!c?'':a.drifted?'drifted':'satisfied');$('#confirmation').innerHTML=!c?'<div class="empty">满足条件后才可显式确认。</div>':'<div class="source"><strong>'+esc(c.profile_key)+' · Project revision '+c.confirmed_project_revision+'</strong><p>确认时间：'+new Date(c.confirmed_at).toLocaleString('zh-CN')+'</p><p>'+c.sources.map(x=>esc(x.result_kind)+' r'+x.revision+' · '+esc(x.digest.slice(0,16))+'…').join('<br>')+'</p></div>'}
async function load(){if(!state.token){$('#credentialDialog').showModal();return}state.projectID=$('#projectID').value.trim().toLowerCase();if(!state.projectID)return;try{notice('正在执行零写入完成评估…');state.assessment=await api('../api/v1/projects/'+encodeURIComponent(state.projectID)+'/completion-assessment?profile='+PROFILE);render();notice(state.assessment.drifted?'已读取：当前来源与最近确认不一致，需要显式重评。':'评估完成；读取没有改变 Project revision。',state.assessment.drifted?'':'ok')}catch(e){state.assessment=null;$('#confirm').disabled=true;notice(e.status===503?'结果服务暂不可用；Project 没有发生写入。':'评估失败：'+e.message,'error')}}
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;state.token=$('#token').value.trim();sessionStorage.setItem('project-demo-token',state.token);setTimeout(load)};$('#projectForm').onsubmit=e=>{e.preventDefault();load()};$('#confirm').onclick=async()=>{const a=state.assessment;if(!a)return;try{$('#confirm').disabled=true;notice('正在确认精确来源；只会写 Project 自己的检查点…');await api('../api/v1/projects/'+encodeURIComponent(state.projectID)+'/completion-confirmations',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:a.project_revision,profile_key:PROFILE,expected_sources:sources()})});await load();notice('C5 检查点已确认；Project 增加一个 revision，Results 未被改写。','ok')}catch(e){notice('确认失败：'+e.message+(e.status===409?'。来源或 Project revision 已变化，请重新评估。':''),'error');$('#confirm').disabled=false}};const requested=new URLSearchParams(location.search).get('project_id');if(requested){$('#projectID').value=requested;if(state.token)load()}`
